// Edite aqui. É o único lugar com endereço da ponte, token, portas e limites.
const entrada = $input.first().json;
const desligar = Object.prototype.hasOwnProperty.call(entrada, 'Quais servidores desligar');

// Quais servidores: o texto escolhido no formulário ("Só o gerador...", "Só o gerenciador...", senão os dois).
const escolha = String(entrada['Quais servidores ligar'] || entrada['Quais servidores desligar'] || '');
let servidores = ['gerador', 'gerenciador'];
if (/^Só o gerador/i.test(escolha)) servidores = ['gerador'];
else if (/^Só o gerenciador/i.test(escolha)) servidores = ['gerenciador'];

// Tempo ligado, em minutos: o que a pessoa digitou, de 5 a 240. Vazio = 60.
let minutos = Number(entrada['Minutos ligados']);
if (!Number.isFinite(minutos) || minutos <= 0) minutos = 60;
minutos = Math.min(Math.max(Math.round(minutos), 5), 240);

return [{ json: {
  acao: desligar ? 'desligar' : 'ligar',
  minutos,
  servidores,
  alvo: servidores.length === 2 ? 'todos' : servidores[0],  // o que a ponte recebe em /servidores/<alvo>/parar
  // A ponte roda no computador, como o usuário cadu (scripts/ponte.py). De dentro do container
  // runv2-n8n-1 o computador é o gateway da rede runv2_default: 172.19.0.1.
  url_ponte: 'http://172.19.0.1:7777',
  token_ponte: '_CHAVE_CHAVE__CHAVE_CHAVE__CHAVE_CHAVE_',
  porta_gerador: 7000,
  porta_gerenciador: 8000,
} }];

const cfg = $('Configuração').first().json;
const r = $input.first().json;
const nomes = { gerador: 'Gerador de imagens', gerenciador: 'Gerenciador de carrosséis' };
const portas = { gerador: cfg.porta_gerador, gerenciador: cfg.porta_gerenciador };

if (r.erros || !Array.isArray(r.servidores)) {
  const motivo = (r.erros && r.erros[0] && r.erros[0].mensagem) || 'resposta inesperada da ponte';
  return [{ json: { estado: 'erro', titulo: 'Não consegui verificar os servidores',
    detalhes: ['A ponte recusou o pedido: ' + motivo + '. Confira o token no nó Configuração.'] } }];
}

const ocupados = [];
for (const s of r.servidores) {
  if (!cfg.servidores.includes(s.servidor)) continue;  // o que não foi escolhido não importa
  const quem = nomes[s.servidor] + ' (porta ' + portas[s.servidor] + ')';
  if (s.rodando) {
    ocupados.push(quem + ': já está ligado e em uso. Pode ser outra pessoa, ou um fluxo em andamento (como a geração de notícias).');
  } else if (s.porta_ocupada) {
    ocupados.push(quem + ': a porta está ocupada por outro programa do computador.');
  }
}
if (ocupados.length) {
  return [{ json: { estado: 'ocupado', titulo: 'Servidor ocupado: nada foi ligado nem desligado', detalhes: ocupados } }];
}
return [{ json: { estado: 'livre' } }];

const j = $input.first().json;
const linhas = (j.detalhes || []).map(d => '• ' + d);
linhas.push('', 'Tente de novo quando o outro uso terminar.');
return [{ json: { titulo: j.titulo, mensagem: linhas.join('\n') } }];

// Um item por servidor escolhido; os próximos nós rodam uma vez para cada item.
const cfg = $('Configuração').first().json;
const info = {
  gerador: { nome: 'Gerador de imagens', porta: cfg.porta_gerador, saude: '/gerador/api/v1/health' },
  gerenciador: { nome: 'Gerenciador de carrosséis', porta: cfg.porta_gerenciador, saude: '/gerenciador/api/v1/saude' },
};
return cfg.servidores.map(s => ({ json: Object.assign({ servidor: s }, info[s]) }));

// Todos os escolhidos já foram mandados ligar, um logo depois do outro: eles iniciam ao mesmo tempo.
const escolhidos = $('Servidores escolhidos').all().map(i => i.json);
const problemas = [];
$input.all().forEach((it, i) => {
  const r = it.json;
  if (r.ok !== true) {
    const motivo = r.mensagem || (r.erros && r.erros[0] && r.erros[0].mensagem) || r.error || 'a ponte não conseguiu ligar';
    problemas.push(escolhidos[i].servidor + ': ' + (typeof motivo === 'string' ? motivo : JSON.stringify(motivo)));
  }
});
if (problemas.length) throw new Error('Não consegui ligar: ' + problemas.join(' | '));
return escolhidos.map(e => ({ json: e }));

const escolhidos = $('Servidores escolhidos').all().map(i => i.json);
const problemas = [];
$input.all().forEach((it, i) => {
  const r = it.json, e = escolhidos[i];
  if (r.error) problemas.push(e.nome + ' ligou, mas não respondeu: ' + (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))));
  else if (e.servidor === 'gerador' && r.ready !== true) {
    problemas.push('Gerador de imagens ligou, mas não está pronto: ' + ((r.problems || []).join(' | ') || 'sem detalhe'));
  }
});
if (problemas.length) throw new Error(problemas.join(' | '));
return [{ json: { ok: true } }];

const cfg = $('Configuração').first().json;
const fim = new Date(Date.now() + cfg.minutos * 60000);
const hora = fim.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
const info = {
  gerador: ['Gerador de imagens', cfg.porta_gerador],
  gerenciador: ['Gerenciador de carrosséis', cfg.porta_gerenciador],
};
const links = cfg.servidores.map(s => {
  const url = 'http://127.0.0.1:' + info[s][1];
  return '<b>' + info[s][0] + ':</b> <a href="' + url + '" target="_blank">' + url + '</a>';
});
const plural = cfg.servidores.length > 1;
const linhas = [
  (plural ? 'Ligados' : 'Ligado') + ' por ' + cfg.minutos + ' minutos: ' + (plural ? 'desligam sozinhos' : 'desliga sozinho') + ' às ' + hora + '.',
  '',
  ...links,
  '',
  'Abra os endereços neste computador. Para desligar antes, use o formulário Desligar.',
];
return [{ json: { titulo: plural ? 'Servidores ligados' : 'Servidor ligado', mensagem: linhas.join('\n'), desliga_as: hora } }];

const r = $input.first().json;
const desligou = r.ok === true;
return [{ json: { ok: desligou, mensagem: desligou ? 'Tempo esgotado: servidores desligados.' : 'Tempo esgotado, mas não consegui confirmar o desligamento. Confira as portas dos servidores escolhidos (7000 e 8000).', resposta_da_ponte: r } }];

const j = $input.first().json;
let motivo;
const e = j.error;
if (typeof e === 'string') motivo = e;
else if (e && (e.message || e.description)) motivo = (e.message || '') + (e.description ? ' — ' + e.description : '');
else if (j.mensagem) motivo = j.mensagem;
else motivo = 'falha sem detalhe: ' + JSON.stringify(j).slice(0, 400);
return [{ json: { motivo } }];

const motivo = $('Montar mensagem de falha').first().json.motivo;
const desligou = $input.first().json.ok === true;
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linhas = ['Motivo: ' + esc(motivo), '',
  desligou ? 'Os servidores escolhidos foram desligados.' : 'Não consegui confirmar o desligamento (a ponte pode estar fora do ar). Confira as portas 7000 e 8000.'];
return [{ json: { titulo: 'Não foi possível ligar os servidores', mensagem: linhas.join('\n') } }];

const r = $input.first().json;
let linhas;
// "todos" devolve {servidores:[...]}; um servidor só devolve o próprio resultado.
const lista = Array.isArray(r.servidores) ? r.servidores : (r.ok === true && r.servidor ? [r] : null);
if (r.ok === true && lista) {
  linhas = [''].concat(lista.map(s => '• ' + s.servidor + ': ' + (s.parou ? 'desligado' : (s.mensagem || 'nada a desligar'))));
  linhas.push('', 'Servidores que não foram ligados por este fluxo não são desligados por ele.');
} else {
  const motivo = (r.erros && r.erros[0] && r.erros[0].mensagem) || (r.error && (r.error.message || r.error)) || 'a ponte não respondeu';
  linhas = ['Motivo: ' + String(motivo).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'), 'Confira as portas 7000 e 8000.'];
}
const ok = r.ok === true && !!lista;
return [{ json: { titulo: ok ? 'Servidores desligados' : 'Não consegui desligar', mensagem: linhas.join('\n').trim() } }];
